1	"use client";
2	
3	import { useCallback, useEffect, useState } from "react";
4	import { useRouter } from "next/navigation";
5	import { getWorkspace } from "@/services/workspace-store";
6	import type { StoredWorkspace } from "@/types/workspace";
7	import { BoardHeader } from "@/features/board/components/BoardHeader";
8	import {
9	  getStoredPanelSelection,
10	  savePanelSelection,
11	} from "@/features/board/lib/panel-selection-store";
12	
13	import {
14	  BoardProvider,
15	  KanbanBoard,
16	} from "@/features/board/components/KanbanBoard";
17	import {
18	  TaskTrackingDetailPanel,
19	  TaskTrackingPanel,
20	  type PanelSelection,
21	} from "@/features/board/components/TaskTrackingPanel";
22	import { TaskDetailSheetMount } from "@/features/tasks";
23	
24	export default function BoardPage() {
25	  const router = useRouter();
26	  const [workspace, setWorkspace] = useState<StoredWorkspace | null>(null);
27	  const [resolved, setResolved] = useState(false);
28	  const [selectedPanel, setSelectedPanel] =
29	    useState<PanelSelection>("kanban_board");
30	
31	  useEffect(() => {
32	    const stored = getWorkspace();
33	    if (!stored) {
34	      router.replace("/connect");
35	      return;
36	    }
37	    setSelectedPanel(getStoredPanelSelection() ?? "kanban_board");
38	    setWorkspace(stored);
39	    setResolved(true);
40	  }, [router]);
41	
42	  const handleSelectPanel = useCallback((panel: PanelSelection) => {
43	    setSelectedPanel(panel);
44	    savePanelSelection(panel);
45	  }, []);
46	
47	  if (!resolved || !workspace) {
48	    return (
49	      <main className="flex min-h-screen flex-col bg-bg">
50	        <div className="flex flex-1 items-center justify-center">
51	          <p className="text-sm text-text-muted">Resolving workspace…</p>
52	        </div>
53	      </main>
54	    );
55	  }
56	
57	  return (
58	    <main className="flex h-screen flex-col bg-bg">
59	      <BoardProvider workspace={workspace}>
60	        <BoardHeader />
61	        <div className="flex flex-1 overflow-hidden">
62	          <TaskTrackingPanel
63	            selectedPanel={selectedPanel}
64	            onSelectPanel={handleSelectPanel}
65	          />
66	          {selectedPanel === "kanban_board" ? (
67	            <section className="min-w-0 flex-1 overflow-hidden p-6">
68	              <KanbanBoard />
69	            </section>
70	          ) : (
71	            <TaskTrackingDetailPanel selectedPanel={selectedPanel} />
72	          )}
73	        </div>
74	        <TaskDetailSheetMount />
75	      </BoardProvider>
76	    </main>
77	  );
78	}
