1	"use client";
2	
3	import { Check, Clock3, Layers3, Zap } from "lucide-react";
4	import { useMemo } from "react";
5	import { useBoardContext } from "../KanbanBoard/KanbanBoard.context";
6	import { groupTrackedTasks } from "./groupTasks";
7	import type { PanelSelection, TrackedStatus } from "./TaskTrackingPanel.types";
8	
9	const PANEL_ORDER: TrackedStatus[] = ["in_review", "in_progress", "ready"];
10	
11	const STATUS_ICON = {
12	  in_review: Clock3,
13	  in_progress: Zap,
14	  ready: Check,
15	} satisfies Record<TrackedStatus, typeof Clock3>;
16	
17	const STATUS_STYLE = {
18	  in_review: "bg-purple-bg text-purple",
19	  in_progress: "bg-warning-bg text-warning",
20	  ready: "bg-primary-light text-primary",
21	} satisfies Record<TrackedStatus, string>;
22	
23	type TaskTrackingPanelProps = {
24	  selectedPanel: PanelSelection;
25	  onSelectPanel: (panel: PanelSelection) => void;
26	};
27	
28	export function TaskTrackingPanel({
29	  selectedPanel,
30	  onSelectPanel,
31	}: TaskTrackingPanelProps) {
32	  const { trackedFeatures } = useBoardContext();
33	
34	  const sections = useMemo(
35	    () => groupTrackedTasks(trackedFeatures),
36	    [trackedFeatures],
37	  );
38	  const orderedSections = useMemo(
39	    () =>
40	      PANEL_ORDER.map((status) => sections.find((section) => section.status === status))
41	        .filter((section): section is (typeof sections)[number] => Boolean(section)),
42	    [sections],
43	  );
44	  const isBoardSelected = selectedPanel === "kanban_board";
45	
46	  return (
47	    <aside
48	      className="flex w-72 shrink-0 flex-col border-r border-border bg-surface-secondary"
49	      aria-label="Task tracking panel"
50	    >
51	      <button
52	        type="button"
53	        onClick={() => onSelectPanel("kanban_board")}
54	        className={
55	          "flex h-10 w-full items-center gap-2 border-b border-border border-l-2 px-4 text-left transition-colors hover:bg-surface " +
56	          (isBoardSelected
57	            ? "border-l-success "
58	            : "border-l-transparent bg-surface-secondary")
59	        }
60	        aria-pressed={isBoardSelected}
61	      >
62	        <Layers3 className="h-3.5 w-3.5 text-success" aria-hidden="true" />
63	        <h2 className="text-[11px] font-bold uppercase tracking-wider text-text-secondary">
64	          Kanban Board
65	        </h2>
66	      </button>
67	      <div className="flex-1 overflow-y-auto">
68	        {orderedSections.map((section) => {
69	          const Icon = STATUS_ICON[section.status];
70	          const isActive = selectedPanel === section.status;
71	
72	          return (
73	            <button
74	              key={section.status}
75	              type="button"
76	              onClick={() => onSelectPanel(section.status)}
77	              className={
78	                "flex h-11 w-full items-center justify-between border-b border-l-2 border-border px-4 text-left transition-colors hover:bg-surface " +
79	                (isActive
80	                  ? "border-l-primary bg-surface"
81	                  : "border-l-transparent bg-surface-secondary")
82	              }
83	              aria-pressed={isActive}
84	            >
85	              <span className="flex min-w-0 items-center gap-2">
86	                <span
87	                  className={
88	                    "flex h-5 w-5 shrink-0 items-center justify-center " +
89	                    STATUS_STYLE[section.status]
90	                  }
91	                >
92	                  <Icon className="h-3 w-3" aria-hidden="true" />
93	                </span>
94	                <span className="truncate text-[11px] font-bold uppercase tracking-wider text-text-secondary">
95	                  {section.label}
96	                </span>
97	              </span>
98	              <span className="rounded bg-muted-bg px-1.5 py-0.5 font-mono text-[10px] text-text-secondary">
99	                {section.items.length}
100	              </span>
101	            </button>
102	          );
103	        })}
104	      </div>
105	    </aside>
106	  );
107	}
