1	"use client";
2	
3	import {
4	  createContext,
5	  useCallback,
6	  useContext,
7	  useMemo,
8	  useState,
9	  type ReactNode,
10	} from "react";
11	import type { ParsedFeature, ParsedTask } from "@/services/yaml-parser";
12	import type { StoredWorkspace } from "@/types/workspace";
13	import { useBoardData, type UseBoardDataOptions } from "../../hooks/useBoardData";
14	import { usePullRequestTaskData } from "../../hooks/usePullRequestTaskData";
15	import type { ActiveFilters, BoardLoadError } from "../../types";
16	
17	export type SelectedTask = {
18	  task: ParsedTask;
19	  featureId: string;
20	  featureTitle: string;
21	} | null;
22	
23	export type BoardContextValue = {
24	  workspace: StoredWorkspace;
25	  features: ParsedFeature[];
26	  trackedFeatures: ParsedFeature[];
27	  loading: boolean;
28	  error: BoardLoadError | null;
29	  reload: () => void;
30	  searchQuery: string;
31	  setSearchQuery: (query: string) => void;
32	  activeFilters: ActiveFilters;
33	  setActiveFilters: (filters: ActiveFilters) => void;
34	  expandedFeatureIds: Set<string>;
35	  toggleFeature: (featureId: string) => void;
36	  selectedTask: SelectedTask;
37	  setSelectedTask: (task: SelectedTask) => void;
38	};
39	
40	const BoardContext = createContext<BoardContextValue | null>(null);
41	
42	export type BoardProviderProps = {
43	  workspace: StoredWorkspace;
44	  children: ReactNode;
45	} & UseBoardDataOptions;
46	
47	export function BoardProvider({
48	  workspace,
49	  children,
50	  clientFactory,
51	}: BoardProviderProps) {
52	  const { features, loading, error, reload } = useBoardData(workspace, {
53	    clientFactory,
54	  });
55	  const {
56	    trackedFeatures,
57	    reload: reloadTracking,
58	  } = usePullRequestTaskData(workspace, {
59	    clientFactory,
60	  });
61	
62	  const [searchQuery, setSearchQuery] = useState("");
63	  const [activeFilters, setActiveFilters] = useState<ActiveFilters>({
64	    statuses: [],
65	  });
66	  const [expandedFeatureIds, setExpandedFeatureIds] = useState<Set<string>>(
67	    () => new Set(),
68	  );
69	  const [selectedTask, setSelectedTask] = useState<SelectedTask>(null);
70	
71	  const toggleFeature = useCallback((featureId: string) => {
72	    setExpandedFeatureIds((prev) => {
73	      const next = new Set(prev);
74	      if (next.has(featureId)) {
75	        next.delete(featureId);
76	      } else {
77	        next.add(featureId);
78	      }
79	      return next;
80	    });
81	  }, []);
82	
83	  const reloadAll = useCallback(() => {
84	    reload();
85	    reloadTracking();
86	  }, [reload, reloadTracking]);
87	
88	  const value = useMemo<BoardContextValue>(
89	    () => ({
90	      workspace,
91	      features,
92	      trackedFeatures,
93	      loading,
94	      error,
95	      reload: reloadAll,
96	      searchQuery,
97	      setSearchQuery,
98	      activeFilters,
99	      setActiveFilters,
100	      expandedFeatureIds,
101	      toggleFeature,
102	      selectedTask,
103	      setSelectedTask,
104	    }),
105	    [
106	      workspace,
107	      features,
108	      trackedFeatures,
109	      loading,
110	      error,
111	      reloadAll,
112	      searchQuery,
113	      activeFilters,
114	      expandedFeatureIds,
115	      toggleFeature,
116	      selectedTask,
117	    ],
118	  );
119	
120	  return <BoardContext.Provider value={value}>{children}</BoardContext.Provider>;
121	}
122	
123	export function useBoardContext(): BoardContextValue {
124	  const ctx = useContext(BoardContext);
125	  if (!ctx) {
126	    throw new Error("useBoardContext must be used within a BoardProvider");
127	  }
128	  return ctx;
129	}
