1	"use client";
2	
3	import { Funnel, RefreshCw, Search } from "lucide-react";
4	import { useEffect, useMemo, useRef, useState } from "react";
5	import { useBoardContext } from "./KanbanBoard.context";
6	import { FeatureRow } from "../FeatureRow";
7	import { STATUS_COLUMNS } from "../../lib/status";
8	import { matchesSearch, matchesStatusFilter } from "../../lib/filter";
9	import {
10	  isAllStatusFilterSelected,
11	  toggleAllStatusFilter,
12	  toggleStatusFilter,
13	} from "../../lib/status-filter";
14	import {
15	  AccessDeniedState,
16	  EmptyBoardState,
17	  NetworkErrorState,
18	  NoWorkflowDataState,
19	  ParseErrorState,
20	} from "../ErrorStates";
21	
22	const MIN_COLUMN_WIDTH = 180;
23	
24	function ColumnHeader({
25	  label,
26	  color,
27	  count,
28	}: {
29	  label: string;
30	  color: string;
31	  count: number;
32	}) {
33	  return (
34	    <div
35	      className="flex min-w-0 flex-1 items-center justify-between border-r border-border bg-surface-secondary px-3 py-2.5 last:border-r-0"
36	      style={{ minWidth: MIN_COLUMN_WIDTH }}
37	    >
38	      <div className="flex min-w-0 items-center gap-2">
39	        <div
40	          className="h-2 w-2 rounded-sm"
41	          style={{ background: color }}
42	          aria-hidden="true"
43	        />
44	        <span className="truncate text-xs font-semibold uppercase tracking-wide text-text-secondary">
45	          {label}
46	        </span>
47	      </div>
48	      <span
49	        className="rounded px-1.5 py-0.5 text-xs font-semibold"
50	        style={{ color, background: `${color}18` }}
51	      >
52	        {count}
53	      </span>
54	    </div>
55	  );
56	}
57	
58	function EmptyState({ message }: { message: string }) {
59	  return (
60	    <div className="flex flex-1 flex-col items-center justify-center gap-2 py-20">
61	      <p className="text-sm text-text-muted">{message}</p>
62	    </div>
63	  );
64	}
65	
66	function BoardControls() {
67	  const {
68	    loading,
69	    reload,
70	    searchQuery,
71	    setSearchQuery,
72	    activeFilters,
73	    setActiveFilters,
74	  } = useBoardContext();
75	  const [filterOpen, setFilterOpen] = useState(false);
76	  const filterRef = useRef<HTMLDivElement>(null);
77	  const selectedStatuses = new Set(activeFilters.statuses);
78	  const allSelected = isAllStatusFilterSelected(activeFilters.statuses);
79	
80	  useEffect(() => {
81	    if (!filterOpen) return;
82	
83	    function handlePointerDown(event: PointerEvent) {
84	      if (!filterRef.current?.contains(event.target as Node)) {
85	        setFilterOpen(false);
86	      }
87	    }
88	
89	    document.addEventListener("pointerdown", handlePointerDown);
90	    return () => {
91	      document.removeEventListener("pointerdown", handlePointerDown);
92	    };
93	  }, [filterOpen]);
94	
95	  function toggleStatus(status: string) {
96	    setActiveFilters({ statuses: toggleStatusFilter(activeFilters.statuses, status) });
97	  }
98	
99	  function toggleAllStatuses() {
100	    setActiveFilters({
101	      statuses: toggleAllStatusFilter(activeFilters.statuses),
102	    });
103	  }
104	
105	  return (
106	    <div className="flex h-12 shrink-0 items-center justify-end gap-2 border-b border-border bg-surface px-4">
107	      <button
108	        type="button"
109	        onClick={reload}
110	        disabled={loading}
111	        aria-label="Sync board"
112	        className="flex h-8 items-center gap-2 border border-border bg-surface px-3 text-xs font-medium text-text-secondary transition-colors hover:bg-surface-subtle disabled:cursor-not-allowed disabled:opacity-50"
113	      >
114	        <RefreshCw
115	          className={"h-3.5 w-3.5 " + (loading ? "animate-spin" : "")}
116	          aria-hidden="true"
117	        />
118	        {loading ? "Syncing..." : "Sync"}
119	      </button>
120	      <label className="flex h-8 w-64 items-center gap-2 border border-border bg-surface px-3 text-xs text-text-secondary focus-within:border-primary">
121	        <Search className="h-3.5 w-3.5 shrink-0" aria-hidden="true" />
122	        <span className="sr-only">Search board</span>
123	        <input
124	          type="search"
125	          value={searchQuery}
126	          onChange={(e) => setSearchQuery(e.target.value)}
127	          placeholder="Search..."
128	          className="min-w-0 flex-1 bg-transparent text-xs text-text-primary outline-none placeholder:text-text-muted"
129	        />
130	      </label>
131	      <div ref={filterRef} className="relative">
132	        <button
133	          type="button"
134	          onClick={() => setFilterOpen((open) => !open)}
135	          aria-expanded={filterOpen}
136	          aria-haspopup="menu"
137	          className="flex h-8 items-center gap-2 border border-border bg-surface px-3 text-xs font-medium text-text-secondary transition-colors hover:bg-surface-subtle"
138	        >
139	          <Funnel className="h-3.5 w-3.5" aria-hidden="true" />
140	          Filter
141	        </button>
142	        {filterOpen && (
143	          <div
144	            role="menu"
145	            className="absolute right-0 top-9 z-30 w-48 border border-border bg-surface p-2 shadow-lg"
146	          >
147	            <label className="mb-1 flex cursor-pointer items-center gap-2 border-b border-border px-2 py-1.5 pb-2 text-xs font-semibold text-text-primary hover:bg-surface-subtle">
148	              <input
149	                type="checkbox"
150	                checked={allSelected}
151	                onChange={toggleAllStatuses}
152	                className="h-3 w-3 accent-primary"
153	              />
154	              All
155	            </label>
156	            {STATUS_COLUMNS.map((status) => (
157	              <label
158	                key={status.key}
159	                className="flex cursor-pointer items-center gap-2 px-2 py-1.5 text-xs text-text-secondary hover:bg-surface-subtle"
160	              >
161	                <input
162	                  type="checkbox"
163	                  checked={selectedStatuses.has(status.key)}
164	                  onChange={() => toggleStatus(status.key)}
165	                  className="h-3 w-3 accent-primary"
166	                />
167	                <span
168	                  className="h-2 w-2 rounded-sm"
169	                  style={{ background: status.color }}
170	                  aria-hidden="true"
171	                />
172	                {status.label}
173	              </label>
174	            ))}
175	          </div>
176	        )}
177	      </div>
178	    </div>
179	  );
180	}
181	
182	export function KanbanBoard() {
183	  const {
184	    features,
185	    loading,
186	    error,
187	    searchQuery,
188	    activeFilters,
189	    expandedFeatureIds,
190	    toggleFeature,
191	    setSelectedTask,
192	  } = useBoardContext();
193	
194	  const visibleFeatures = useMemo(
195	    () =>
196	      features.filter(
197	        (f) =>
198	          matchesSearch(f, searchQuery) &&
199	          matchesStatusFilter(f, activeFilters.statuses),
200	      ),
201	    [features, searchQuery, activeFilters],
202	  );
203	
204	  const columnCounts = useMemo(() => {
205	    const counts: Record<string, number> = {};
206	    for (const col of STATUS_COLUMNS) counts[col.key] = 0;
207	    for (const feature of visibleFeatures) {
208	      for (const task of feature.tasks) {
209	        if (task.status in counts) counts[task.status]++;
210	      }
211	    }
212	    return counts;
213	  }, [visibleFeatures]);
214	
215	  let content;
216	  if (loading) {
217	    content = (
218	      <div className="flex flex-1 items-center justify-center">
219	        <p className="text-sm text-text-muted">Loading board...</p>
220	      </div>
221	    );
222	  } else if (error) {
223	    if (error.kind === "access_denied") {
224	      content = <AccessDeniedState message={error.message} />;
225	    } else if (error.kind === "not_found") {
226	      content = <NoWorkflowDataState message={error.message} />;
227	    } else if (error.kind === "parse_error") {
228	      content = <ParseErrorState message={error.message} />;
229	    } else {
230	      content = <NetworkErrorState message={error.message} />;
231	    }
232	  } else if (features.length === 0) {
233	    content = <EmptyBoardState />;
234	  } else if (visibleFeatures.length === 0) {
235	    content = (
236	      <EmptyState message="No features match the current search or filters." />
237	    );
238	  } else {
239	    content = (
240	      <div className="min-h-0 flex-1 overflow-auto">
241	        <div
242	          className="w-full"
243	          style={{ minWidth: MIN_COLUMN_WIDTH * STATUS_COLUMNS.length }}
244	        >
245	          <div
246	            className="sticky top-0 z-10 flex w-full border-b border-border"
247	            role="row"
248	            aria-label="Status columns"
249	          >
250	            {STATUS_COLUMNS.map((col) => (
251	              <ColumnHeader
252	                key={col.key}
253	                label={col.label}
254	                color={col.color}
255	                count={columnCounts[col.key] ?? 0}
256	              />
257	            ))}
258	          </div>
259	
260	          <div role="list" aria-label="Features" className="bg-surface">
261	            {visibleFeatures.map((feature) => (
262	              <div key={feature.id} role="listitem">
263	                <FeatureRow
264	                  feature={feature}
265	                  isExpanded={expandedFeatureIds.has(feature.id)}
266	                  onToggle={() => toggleFeature(feature.id)}
267	                  onSelectTask={setSelectedTask}
268	                  minColumnWidth={MIN_COLUMN_WIDTH}
269	                />
270	              </div>
271	            ))}
272	          </div>
273	        </div>
274	      </div>
275	    );
276	  }
277	
278	  return (
279	    <div className="flex h-full min-h-0 flex-1 flex-col overflow-hidden border border-border bg-surface">
280	      <BoardControls />
281	      {content}
282	    </div>
283	  );
284	}
