1	"use client";
2	
3	import { Clock3, ExternalLink, GitBranch, ListChecks } from "lucide-react";
4	import { useMemo } from "react";
5	import { getElapsedSinceStatus } from "@/lib/time";
6	import { useBoardContext } from "../KanbanBoard/KanbanBoard.context";
7	import { groupTrackedTasks } from "./groupTasks";
8	import type {
9	  PanelSelection,
10	  TrackedStatus,
11	  TrackedTaskItem,
