8	function isOpenPullRequestStatus(status: string | undefined): boolean {
9	  return status?.toLowerCase() === "open";
10	}
11	
12	function hasOpenPullRequest(task: ParsedFeature["tasks"][number]): boolean {
13	  return (
14	    isOpenPullRequestStatus(task.pr?.status) ||
15	    isOpenPullRequestStatus(task.workspace_pr?.status)
16	  );
17	}
18	
19	export function groupTrackedTasks(
20	  features: ParsedFeature[],
21	): TrackedSection[] {
22	  const buckets = new Map<TrackedStatus, TrackedSection>();
23	  for (const { status, label } of TRACKED_SECTIONS) {
24	    buckets.set(status, { status, label, items: [] });
25	  }
26	
27	  for (const feature of features) {
28	    for (const task of feature.tasks) {
29	      if (!hasOpenPullRequest(task)) continue;
30	      
31	      const bucket = buckets.get(task.status as TrackedStatus);
32	      if (bucket) {
33	        bucket.items.push({ task, feature });
34	      }
35	    }
36	  }
37	
38	  return TRACKED_SECTIONS.map(({ status }) => buckets.get(status)!);
39	}
