1	import { load as yamlLoad } from "js-yaml";
2	
3	export type LogEntry = {
4	  action: string;
5	  by: string;
6	  at: string;
7	  note?: string;
8	};
9	
10	export type ParsedTask = {
11	  id: string;
12	  title: string;
13	  status: string;
14	  dependsOn: string[];
15	  execution?: { actor_type: string; last_updated_by?: string; last_updated_at?: string };
16	  branch?: string;
17	  pr?: { url?: string; status?: string };
18	  workspace_pr?: { url?: string; status?: string };
19	  blockedReason?: string;
20	  blockedContext?: Record<string, unknown>;
21	  log?: LogEntry[];
22	};
23	
24	export type ParsedFeature = {
25	  id: string;
26	  title: string;
27	  featureStatus: string;
28	  tasks: ParsedTask[];
29	};
30	
31	type RawFeatureStatus = {
32	  feature_id?: string;
33	  title?: string;
34	  feature_status?: string;
35	  stage?: string;
36	};
37	
38	type RawTask = {
39	  id?: string;
40	  title?: string;
41	  status?: string;
42	  depends_on?: string[];
43	  execution?: { actor_type?: string; last_updated_by?: string; last_updated_at?: string };
44	  branch?: string;
45	  pr?: { url?: string; status?: string };
46	  workspace_pr?: { url?: string; status?: string };
47	  blocked_reason?: string;
48	  blocked_context?: Record<string, unknown>;
49	  log?: Array<{ action?: string; by?: string; at?: string; note?: string }>;
50	};
51	
52	export function parseFeatureStatus(
53	  raw: string,
54	  featureId?: string,
55	): RawFeatureStatus {
56	  try {
57	    return (yamlLoad(raw) as RawFeatureStatus) ?? {};
58	  } catch (err) {
59	    const id = featureId ?? "<unknown>";
60	    console.warn(`[yaml-parser] Failed to parse status.yaml for ${id}:`, err);
61	    return {};
62	  }
63	}
64	
65	export function parseTaskYaml(id: string, raw: string): ParsedTask | null {
66	  let data: RawTask;
67	  try {
68	    data = (yamlLoad(raw) as RawTask) ?? {};
69	  } catch (err) {
70	    console.warn(`[yaml-parser] Failed to parse task YAML for ${id}:`, err);
71	    return null;
72	  }
73	
74	  if (!data || typeof data !== "object") {
75	    console.warn(`[yaml-parser] Malformed task YAML for ${id}: not an object`);
76	    return null;
77	  }
78	
79	  const log: LogEntry[] | undefined = Array.isArray(data.log)
80	    ? data.log
81	        .filter(
82	          (e) =>
83	            e &&
84	            typeof e.action === "string" &&
85	            typeof e.by === "string" &&
86	            typeof e.at === "string",
87	        )
88	        .map((e) => ({
89	          action: e.action as string,
90	          by: e.by as string,
91	          at: e.at as string,
92	          ...(e.note !== undefined ? { note: e.note } : {}),
93	        }))
94	    : undefined;
95	
96	  return {
97	    id: typeof data.id === "string" ? data.id : id,
98	    title: typeof data.title === "string" ? data.title : "",
99	    status: typeof data.status === "string" ? data.status : "unknown",
100	    dependsOn: Array.isArray(data.depends_on)
101	      ? data.depends_on.filter((d) => typeof d === "string")
102	      : [],
103	    ...(data.execution?.actor_type
104	      ? {
105	          execution: {
106	            actor_type: data.execution.actor_type,
107	            ...(typeof data.execution.last_updated_by === "string"
108	              ? { last_updated_by: data.execution.last_updated_by }
109	              : {}),
110	            ...(typeof data.execution.last_updated_at === "string"
111	              ? { last_updated_at: data.execution.last_updated_at }
112	              : {}),
113	          },
114	        }
115	      : {}),
116	    ...(typeof data.branch === "string" ? { branch: data.branch } : {}),
117	    ...(data.pr !== undefined ? { pr: data.pr } : {}),
118	    ...(data.workspace_pr !== undefined ? { workspace_pr: data.workspace_pr } : {}),
119	    ...(typeof data.blocked_reason === "string" && data.blocked_reason !== null
120	      ? { blockedReason: data.blocked_reason }
121	      : {}),
122	    ...(data.blocked_context != null && typeof data.blocked_context === "object"
123	      ? { blockedContext: data.blocked_context }
124	      : {}),
125	    ...(log !== undefined ? { log } : {}),
126	  };
127	}
